const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Canada geometry and date
  const canada = ee.FeatureCollection('USDOS/LSIB_SIMPLE/2017')
    .filter(ee.Filter.eq('country_na', 'Canada'));
  const canadaGeom = canada.geometry();

  const targetDate = '2023-10-24';

  // 2. Try MODIS Thermal Anomalies/Fire product
  let fireCollection = ee.ImageCollection('MODIS/061/MOD14A1')
    .filterDate(targetDate, '2023-10-25')
    .filterBounds(canadaGeom);

  const collectionSize = fireCollection.size().getInfo();
  console.log(`MODIS fire images found: ${collectionSize}`);

  if (collectionSize === 0) {
    // Try VIIRS as fallback
    fireCollection = ee.ImageCollection('MODIS/061/MYD14A1')
      .filterDate(targetDate, '2023-10-25')
      .filterBounds(canadaGeom);

    const fallbackSize = fireCollection.size().getInfo();
    console.log(`Fallback MYD14A1 images found: ${fallbackSize}`);

    if (fallbackSize === 0) {
      console.log('No fire detection data available for Oct 24, 2023');
      console.log('<answer>C1</answer>');
      return;
    }
  }

  // 3. Get fire mask band and count fire pixels
  const fireImage = fireCollection.first();
  const fireMask = fireImage.select('FireMask');

  // Count total pixels
  const pixelCount = fireMask.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: canadaGeom,
    scale: 1000,
    maxPixels: 1e9
  }).get('FireMask').getInfo();

  console.log(`Total pixels analyzed: ${pixelCount}`);

  if (pixelCount === 0) {
    console.log('No valid pixels after processing');
    console.log('<answer>C2</answer>');
    return;
  }

  // 4. Count fire pixels (FireMask values 7-9 indicate fires)
  const firePixels = fireMask.gte(7);
  const fireCount = firePixels.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: canadaGeom,
    scale: 1000,
    maxPixels: 1e9
  }).get('FireMask').getInfo();

  console.log(`Fire pixels detected: ${fireCount}`);

  // 5. Validation and final answer
  if (fireCount === null || fireCount === undefined) {
    console.log('Calculation failed - invalid result');
    console.log('<answer>C3</answer>');
    return;
  }

  if (fireCount > 0) {
    console.log(`Active fires confirmed in Canada on Oct 24, 2023`);
    console.log('<answer>A</answer>');
  } else {
    console.log('No active fires detected in Canada on Oct 24, 2023');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
